use kernel::{value::read_json, Config, Engine, Input};
use serde_json::{json,Value};
use std::path::PathBuf;
// 内核输出§2：区分恢复入口与事后独立身份校验的实际覆盖。
fn main(){
 let args:Vec<String>=std::env::args().collect();let root=PathBuf::from(&args[1]);
 let config=Config::parse(read_json(&root.join("规格/内核配置-v1.json")).unwrap()).unwrap();
 let mut rows=Vec::new();
 for name in ["restart-control","movement-build-alias","movement-future-id"] {
  let path=root.join(format!("crates/kernel/复核/r2-工程证据/{}-input.json",name));
  let mut engine=Engine::new(Input::load(&path,&config,false).unwrap()).unwrap();
  let start=json!(engine.state);let tick=engine.step(true).unwrap().unwrap();
  let result=kernel::event_identity::validate_event_identity(&engine.input,&start,&[tick]);
  rows.push(json!({"case":name,"identity_after_step":result.map_err(|e|e.to_string())}));
 }
 let _:Value=json!(null);println!("{}",json!(rows));
}
